{"cells":[{"cell_type":"markdown","metadata":{"id":"SN8H1wkXPXZ9"},"source":["# RSA"]},{"cell_type":"code","execution_count":null,"metadata":{"id":"cdtAO8nJT2kf","executionInfo":{"status":"ok","timestamp":1785751789410,"user_tz":-360,"elapsed":6,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"f0dce26e-9b9d-4d69-c045-096047a81a89","colab":{"base_uri":"https://localhost:8080/"}},"outputs":[{"output_type":"stream","name":"stdout","text":["91694925243764\n"]}],"source":["m = int(\"Secret\".encode(\"utf-8\").hex(),16)\n","print(m)"]},{"cell_type":"code","source":["import random\n","import sympy\n","\n","# Function to generate a random 128-bit prime number\n","def generate_128_bit_prime():\n","    while True:\n","        # Generate a random 128-bit integer\n","        candidate = random.getrandbits(128)\n","\n","        # Ensure exactly 128 bits and make it odd\n","        candidate |= (1 << 127) | 1\n","\n","        # Check whether candidate is prime\n","        if sympy.isprime(candidate):\n","            return candidate\n","\n","\n","# Fixed public exponent\n","e = 11\n","\n","\n","# Generate p and q until e has an inverse modulo phi(n)\n","while True:\n","\n","    # Generate two different 128-bit primes\n","    p = generate_128_bit_prime()\n","    q = generate_128_bit_prime()\n","\n","    # Ensure p and q are different\n","    if p == q:\n","        continue\n","\n","    # Calculate phi(n)\n","    phi = (p - 1) * (q - 1)\n","\n","    # Check if e and phi are coprime\n","    if sympy.gcd(e, phi) == 1:\n","        break\n","\n","\n","# Calculate n\n","n = p * q\n","\n","\n","# Print values\n","print(\"p =\", p)\n","print(\"q =\", q)\n","\n","print(\"p bit length:\", p.bit_length())\n","print(\"q bit length:\", q.bit_length())\n","\n","print(\"n =\", n)\n","print(\"phi(n) =\", phi)\n","\n","print(\"gcd(e, phi) =\", sympy.gcd(e, phi))"],"metadata":{"id":"u1fe5OEdFGGC","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1785751789472,"user_tz":-360,"elapsed":40,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"9def1520-6b95-488a-8f14-95dabc9bbf0f"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["p = 275125036668981847721010438879886786547\n","q = 177334035173342924270050127011835743721\n","p bit length: 128\n","q bit length: 128\n","n = 48789032929724488794228420087168404274524413761486935342387315776064522521387\n","phi(n) = 48789032929724488794228420087168404274071954689644610570396255210172799991120\n","gcd(e, phi) = 1\n"]}]},{"cell_type":"code","source":["#Calculate n = pq\n","n = p*q\n","print(\"n =\", n)"],"metadata":{"id":"EUgjRdcsNU3a","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1785751789473,"user_tz":-360,"elapsed":7,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"38302c07-17e7-4fa0-c3f9-24f7a97ca036"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["n = 48789032929724488794228420087168404274524413761486935342387315776064522521387\n"]}]},{"cell_type":"code","source":["#Calculate phi(n)=(p-1)(q-1)\n","phi = (p-1)*(q-1)\n","print(\"phi(n) =\", phi)\n","# Check whether e is valid\n","print(\"gcd(e, phi) =\", sympy.gcd(e, phi))"],"metadata":{"id":"xoTaEAEwNaFf","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1785751789488,"user_tz":-360,"elapsed":15,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"19916e5b-9e62-40fb-86a2-8ac85c66cc3b"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["phi(n) = 48789032929724488794228420087168404274071954689644610570396255210172799991120\n","gcd(e, phi) = 1\n"]}]},{"cell_type":"code","execution_count":null,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"Flep_Z78Pak0","executionInfo":{"status":"ok","timestamp":1785751789501,"user_tz":-360,"elapsed":4,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"81e682ef-e911-4614-f464-56691214db30"},"outputs":[{"output_type":"stream","name":"stdout","text":["Original message = 91694925243764\n","Encrypted message = 4631044339558673081033197756653546771678906943855197728604193456628636385106\n"]}],"source":["#Perform encryption here and generate ciphertext [c = m^e (mod n)] and private key [d*e ≡ 1 (mod(phi(n)))]\n","e = 11\n","\n","c = pow(m, e, n)\n","\n","print(\"Original message =\", m)\n","print(\"Encrypted message =\", c)"]},{"cell_type":"code","source":["# Extended Euclidean Algorithm\n","def gcdExtended(a, b, x, y):\n","\n","    # Base case\n","    if a == 0:\n","        x[0] = 0\n","        y[0] = 1\n","        return b\n","\n","    x1, y1 = [0], [0]\n","\n","    gcd = gcdExtended(b % a, a, x1, y1)\n","\n","    # Update x and y\n","    x[0] = y1[0] - (b // a) * x1[0]\n","    y[0] = x1[0]\n","\n","    return gcd\n","\n","\n","# Find modular inverse of e\n","x, y = [0], [0]\n","\n","gcd = gcdExtended(e, phi, x, y)\n","\n","if gcd != 1:\n","    print(\"Inverse does not exist\")\n","else:\n","    # d*e ≡ 1 (mod phi)\n","    d = x[0] % phi\n","\n","    print(\"d =\", d)\n","    print(\"Verification =\", (d * e) % phi)"],"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"xTiPEZWT4eFj","executionInfo":{"status":"ok","timestamp":1785751789506,"user_tz":-360,"elapsed":4,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"07cf925b-024a-408d-b449-00e136984c59"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["d = 8870733259949907053496076379485164413467628125389929194617500947304145452931\n","Verification = 1\n"]}]},{"cell_type":"code","source":["#perform decryption here [m = c^d (mod n)]\n","\n","# Decryption:\n","# m = c^d mod n\n","\n","decrypted_message = pow(c, d, n)\n","\n","\n","print(\"Decrypted message =\", decrypted_message)"],"metadata":{"id":"RAUj3o2c46Vk","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1785751789512,"user_tz":-360,"elapsed":5,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"2edfb1fd-609c-4af0-da50-937921f18172"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["Decrypted message = 91694925243764\n"]}]},{"cell_type":"code","source":["m = 91694925243764 #??\n","print(bytes.fromhex(hex(m)[2:]).decode('utf-8') )"],"metadata":{"id":"sHDbhVSGFN6K","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1785751789519,"user_tz":-360,"elapsed":5,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"acd8c598-39c3-490c-b081-19c1cab565d9"},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["Secret\n"]}]}],"metadata":{"colab":{"provenance":[{"file_id":"11vR3UG-Q8GqfmcKGL4XyVsxwi8fbN1Ee","timestamp":1785746712032},{"file_id":"1lIQJ_IsBT_bb9m_pbRf5BMfrH3Na9uMi","timestamp":1769713096534},{"file_id":"19K5o0j67kZtuGnQyG3B1HahGV0IU18og","timestamp":1754922452488},{"file_id":"1_fJVSPEnFYh-ZPnpw5_DJatilpLrW7tO","timestamp":1700442116843}],"gpuType":"T4"},"kernelspec":{"display_name":"Python 3","name":"python3"},"language_info":{"name":"python"}},"nbformat":4,"nbformat_minor":0}